{
  "findings": [
    {
      "check_id": "CKV_AWS_24",
      "title": "Ensure no security groups allow ingress from 0.0.0.0/0 to port 22",
      "resource": "aws_security_group.vault",
      "severity": "HIGH",
      "explanation": "Allowing ingress from 0.0.0.0/0 to any port, including port 22, exposes the resource to the entire internet, increasing the risk of unauthorized access."
    },
    {
      "check_id": "AVD-AWS-0124",
      "title": "Security group rule does not have a description",
      "resource": "aws_security_group.vault",
      "severity": "LOW",
      "explanation": "Security group rules lack descriptions, which makes it harder to understand the purpose of each rule and maintain the infrastructure securely."
    }
  ],
  "patched_code": "resource "aws_security_group" "vault" {
  name        = "vault"
  description = "Ingress for Vault"
  vpc_id      = aws_vpc.my_vpc.id

  dynamic "ingress" {
    iterator = port
    for_each = var.ingress_ports
    content {
      from_port   = port.value
      to_port     = port.value
      protocol    = "tcp"
      cidr_blocks = var.ingress_cidr_blocks
      description = "Allow ingress for port ${port.value}"
    }
  }
}

variable "ingress_cidr_blocks" {
  description = "List of allowed CIDR blocks for ingress rules"
  type        = list(string)
  default     = ["192.168.0.0/16"]
}",
  "fix_summary": "Restricted ingress CIDR blocks to a private range (192.168.0.0/16) instead of 0.0.0.0/0 to prevent public exposure. Added descriptions to the security group rules for better clarity and maintainability."
}
